def compare_versions(a, b):
    # Split optional pre‑release suffix
    a_main, _, a_suffix = a.partition('-')
    b_main, _, b_suffix = b.partition('-')

    # Convert numeric components to integers (ignoring leading zeros)
    a_nums = [int(x) for x in a_main.split('.')]
    b_nums = [int(x) for x in b_main.split('.')]

    # Compare numeric parts, treating missing parts as 0
    max_len = max(len(a_nums), len(b_nums))
    for i in range(max_len):
        av = a_nums[i] if i < len(a_nums) else 0
        bv = b_nums[i] if i < len(b_nums) else 0
        if av > bv:
            return 1
        if av < bv:
            return -1

    # Numeric parts are equal – handle pre‑release suffixes
    if a_suffix is None and b_suffix is None:
        return 0
    if a_suffix is not None and b_suffix is None:
        return -1
    if a_suffix is None and b_suffix is not None:
        return 1
    # Both have suffixes: lexical order decides
    return -1 if a_suffix < b_suffix else (1 if a_suffix > b_suffix else 0)

