def median(xs):
    """Median of a non-empty list of numbers."""
    if not xs:
        raise ValueError("median() arg is an empty list")
    sorted_xs = sorted(xs)
    n = len(sorted_xs)
    mid = n // 2
    if n % 2:
        return sorted_xs[mid]
    else:
        return (sorted_xs[mid - 1] + sorted_xs[mid]) / 2

