def flatten(nested, depth=None):
    """Flatten nested lists and tuples into a single list.

    - Strings and bytes are treated as atomic values.
    - `depth` limits how many nesting levels are removed; None means full flatten.
    - Raises TypeError if `nested` is not a list or tuple.
    """
    if not isinstance(nested, (list, tuple)):
        raise TypeError("nested must be a list or tuple")

    def _gen(item, depth_left):
        # If we have reached the depth limit, yield the item unchanged.
        if isinstance(item, (list, tuple)):
            if depth_left is None or depth_left > 0:
                for sub in item:
                    yield from _gen(sub, depth_left - 1 if depth_left is not None else None)
            else:
                yield item
        else:
            yield item

    return list(_gen(nested, depth))

