def flatten(nested, depth=None):
    """Flatten nested lists and tuples into a single list respecting depth and atom rules."""
    if not isinstance(nested, (list, tuple)):
        raise TypeError("nested must be a list or tuple")

    def _gen(obj, remaining_depth):
        # If we have consumed the allowed depth, yield the object as‑is
        if isinstance(remaining_depth, int) and remaining_depth == 0:
            yield obj
            return
        # If the object is a list or tuple, iterate into it
        if isinstance(obj, (list, tuple)):
            # Determine the depth to pass to children
            child_depth = None if remaining_depth is None else (remaining_depth - 1)
            for item in obj:
                yield from _gen(item, child_depth)
        else:
            # Strings, bytes, and other non‑list/tuple items are atomic
            yield obj

    return list(_gen(nested, depth))

