import re

def wrap(text, width):
    # Extract non‑whitespace sequences (collapse any whitespace)
    words = re.findall(r'\S+', text)
    lines, cur = [], ""
    for w in words:
        # Determine what the line would look like if we added this word
        if cur == "":
            candidate = w
        else:
            candidate = cur + " " + w
        # If adding the word would exceed the width, finalize current line
        if len(candidate) > width:
            if cur:                     # avoid adding empty lines
                lines.append(cur)
            cur = w                      # start new line with the current word
        else:
            cur = candidate
    if cur:
        lines.append(cur)
    return lines

