def median(xs):
    """Median of a non-empty list of numbers."""
    if not xs:
        raise ValueError("empty list")
    s = sorted(xs)
    n = len(s)
    mid = n // 2
    if n % 2:
        return s[mid]
    return (s[mid-1] + s[mid]) / 2

