def parse_csv_line(line):
    """Parse a single CSV line according to the specified rules."""
    fields = []
    field = []
    in_quotes = False
    i = 0
    while i < len(line):
        ch = line[i]
        if in_quotes:
            if ch == '"':
                # Check for escaped quote ("")
                if i + 1 < len(line) and line[i + 1] == '"':
                    field.append('"')
                    i += 1  # skip the escaped quote
                else:
                    # Closing quote
                    in_quotes = False
            else:
                field.append(ch)
        else:
            if ch == '"':
                in_quotes = True
            elif ch == ',':
                # End of field
                fields.append(''.join(field))
                field = []
                continue
            # Any other character is part of the field
            field.append(ch)
        i += 1

    # If we finish while still inside quotes, the input is malformed
